#define RING_SIZE 256  /* power of two */
typedef struct { uint8_t buf[RING_SIZE];
    volatile uint32_t head; /* written by producer only */
    volatile uint32_t tail; /* written by consumer only */ } ring_t;

int ring_put(ring_t *r, uint8_t b) {
    uint32_t h = r->head;
    if ((uint32_t)(h - r->tail) >= RING_SIZE) return -1; /* full */
    r->buf[h & (RING_SIZE - 1)] = b;
    __DMB();              /* data visible before index moves */
    r->head = h + 1;
    return 0;
}

