uint32_t get_and_clear(volatile uint32_t *flag) {
    uint32_t primask = __get_PRIMASK();
    __disable_irq();
    uint32_t v = *flag;      /* atomic: no ISR can interleave */
    *flag = 0;
    if (!primask) __enable_irq();  /* restore, don't blindly enable */
    return v;
}

#define RB_SIZE 256
static uint8_t rb[RB_SIZE];
static volatile uint16_t wr, rd;   /* wr: ISR only, rd: task only */
bool rb_put(uint8_t b) {
    uint16_t nwr = (wr + 1) & (RB_SIZE - 1);
    if (nwr == rd) return false;    /* full: drop, don't block in ISR */
    rb[wr] = b;
    __DMB();                        /* data before index */
    wr = nwr;
    return true;
}

volatile uint32_t events;
void TIM2_IRQHandler(void) {          /* 1 ms tick */
    TIM2->SR = 0;                     /* clear source */
    events |= EV_TICK;                /* atomic OR on aligned word */
}
int main(void) {
    for (;;) {
        uint32_t e = atomic_take(&events);  /* snapshot + clear */
        if (e & EV_TICK)   handle_tick();
        if (e & EV_SENSOR) handle_sensor();
        __WFI();                        /* sleep until next interrupt */
    }
}

void HardFault_Handler(void) {
    __asm volatile("tst lr, #4\n"
                   "ite eq\n"
                   "mrseq r0, msp\n"
                   "mrsne r0, psp\n"
                   "b hardfault_c\n");
}
void hardfault_c(uint32_t *sp) {
    fault.pc   = sp[6];   /* faulting instruction */
    fault.lr   = sp[5];
    fault.cfsr = SCB->CFSR;
    log_to_flash(&fault);
    NVIC_SystemReset();
}

