/* reverse a singly linked list — the canonical whiteboard problem */
struct node { int val; struct node *next; };
struct node *reverse(struct node *head) {
    struct node *prev = NULL;
    while (head) {
        struct node *nxt = head->next;  /* save before overwrite */
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

